import{_ as t,a0 as p,w as d,s as o,ao as h,I as l,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何統計 Linux 中文件和文件夾/目錄的數量 | LCTT x X-CMD","titleTemplate":false,"description":"如何統計 Linux 中文件和文件夾/目錄的數量 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何統計 Linux 中文件和文件夾/目錄的數量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何統計 Linux 中文件和文件夾/目錄的數量 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux","title":"如何統計 Linux 中文件和文件夾/目錄的數量","tag":"201802","desc":""},"relativePath":"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux.md","filePath":"[post].md"}'),c={name:"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux.md"};function r(g,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何統計-linux-中文件和文件夾-目錄的數量" tabindex="-1">如何統計 Linux 中文件和文件夾/目錄的數量 <a class="header-anchor" href="#如何統計-linux-中文件和文件夾-目錄的數量" aria-label="Permalink to “如何統計 Linux 中文件和文件夾/目錄的數量”">​</a></h1><p>嗨，夥計們，今天我們再次帶來一系列可以多方面幫助到你的複雜的命令。 通過操作命令，可以幫助您計數當前目錄中的文件和目錄、遞歸計數，統計特定用户創建的文件列表等。</p><p>在本教程中，我們將向您展示如何使用多個命令，並使用 <code>ls</code>、<code>egrep</code>、<code>wc</code> 和 <code>find</code> 命令執行一些高級操作。 下面的命令將可用在多個方面。</p><p>為了實驗，我打算總共創建 7 個文件和 2 個文件夾（5 個常規文件和 2 個隱藏文件）。 下面的 <code>tree</code> 命令的輸出清楚的展示了文件和文件夾列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree -a /opt</span></span>
<span class="line"><span>/opt</span></span>
<span class="line"><span>├── magi</span></span>
<span class="line"><span>│   └── 2g</span></span>
<span class="line"><span>│   ├── test5.txt</span></span>
<span class="line"><span>│   └── .test6.txt</span></span>
<span class="line"><span>├── test1.txt</span></span>
<span class="line"><span>├── test2.txt</span></span>
<span class="line"><span>├── test3.txt</span></span>
<span class="line"><span>├── .test4.txt</span></span>
<span class="line"><span>└── test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2 directories, 7 files</span></span></code></pre></div><h3 id="示例-1" tabindex="-1">示例-1 <a class="header-anchor" href="#示例-1" aria-label="Permalink to “示例-1”">​</a></h3><p>統計當前目錄的文件（不包括隱藏文件）。 運行以下命令以確定當前目錄中有多少個文件，並且不計算點文件（LCTT 譯註：點文件即以“.” 開頭的文件，它們在 Linux 默認是隱藏的）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -l . | egrep -c &#39;^-&#39;</span></span>
<span class="line"><span>4</span></span></code></pre></div><p><strong>細節：</strong></p><ul><li><code>ls</code> ： 列出目錄內容</li><li><code>-l</code> ： 使用長列表格式</li><li><code>.</code> ： 列出有關文件的信息（默認為當前目錄）</li><li><code>|</code> ： 將一個程序的輸出發送到另一個程序進行進一步處理的控制操作符</li><li><code>egrep</code> ： 打印符合模式的行</li><li><code>-c</code> ： 通用輸出控制</li><li><code>&#39;^-&#39;</code> ： 以“-”開頭的行（<code>ls -l</code> 列出長列表時，行首的 “-” 代表普通文件）</li></ul><h3 id="示例-2" tabindex="-1">示例-2 <a class="header-anchor" href="#示例-2" aria-label="Permalink to “示例-2”">​</a></h3><p>統計當前目錄包含隱藏文件在內的文件。 包括當前目錄中的點文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -la . | egrep -c &#39;^-&#39;</span></span>
<span class="line"><span>5</span></span></code></pre></div><h3 id="示例-3" tabindex="-1">示例-3 <a class="header-anchor" href="#示例-3" aria-label="Permalink to “示例-3”">​</a></h3><p>運行以下命令來計數當前目錄的文件和文件夾。 它會計算所有的文件和目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -l | wc -l</span></span>
<span class="line"><span>5</span></span></code></pre></div><p><strong>細節：</strong></p><ul><li><code>ls</code> ： 列出目錄內容</li><li><code>-l</code> ： 使用長列表格式</li><li><code>|</code> ： 將一個程序的輸出發送到另一個程序進行進一步處理的控制操作符</li><li><code>wc</code> ： 這是一個統計每個文件的換行符、單詞和字節數的命令</li><li><code>-l</code> ： 輸出換行符的數量</li></ul><h3 id="示例-4" tabindex="-1">示例-4 <a class="header-anchor" href="#示例-4" aria-label="Permalink to “示例-4”">​</a></h3><p>統計當前目錄包含隱藏文件和目錄在內的文件和文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -la | wc -l</span></span>
<span class="line"><span>8</span></span></code></pre></div><h3 id="示例-5" tabindex="-1">示例-5 <a class="header-anchor" href="#示例-5" aria-label="Permalink to “示例-5”">​</a></h3><p>遞歸計算當前目錄的文件，包括隱藏文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -type f | wc -l</span></span>
<span class="line"><span>7</span></span></code></pre></div><p><strong>細節 ：</strong></p><ul><li><code>find</code> ： 搜索目錄結構中的文件</li><li><code>-type</code> ： 文件類型</li><li><code>f</code> ： 常規文件</li><li><code>wc</code> ： 這是一個統計每個文件的換行符、單詞和字節數的命令</li><li><code>-l</code> ： 輸出換行符的數量</li></ul><h3 id="示例-6" tabindex="-1">示例-6 <a class="header-anchor" href="#示例-6" aria-label="Permalink to “示例-6”">​</a></h3><p>使用 <code>tree</code> 命令輸出目錄和文件數（不包括隱藏文件）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree | tail -1</span></span>
<span class="line"><span>2 directories, 5 files</span></span></code></pre></div><h3 id="示例-7" tabindex="-1">示例-7 <a class="header-anchor" href="#示例-7" aria-label="Permalink to “示例-7”">​</a></h3><p>使用包含隱藏文件的 <code>tree</code> 命令輸出目錄和文件計數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree -a | tail -1</span></span>
<span class="line"><span>2 directories, 7 files</span></span></code></pre></div><h3 id="示例-8" tabindex="-1">示例-8 <a class="header-anchor" href="#示例-8" aria-label="Permalink to “示例-8”">​</a></h3><p>運行下面的命令遞歸計算包含隱藏目錄在內的目錄數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -type d | wc -l</span></span>
<span class="line"><span>3</span></span></code></pre></div><h3 id="示例-9" tabindex="-1">示例-9 <a class="header-anchor" href="#示例-9" aria-label="Permalink to “示例-9”">​</a></h3><p>根據文件擴展名計數文件數量。 這裏我們要計算 <code>.txt</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -name &quot;*.txt&quot; | wc -l</span></span>
<span class="line"><span>7</span></span></code></pre></div><h3 id="示例-10" tabindex="-1">示例-10 <a class="header-anchor" href="#示例-10" aria-label="Permalink to “示例-10”">​</a></h3><p>組合使用 <code>echo</code> 命令和 <code>wc</code> 命令統計當前目錄中的所有文件。 <code>4</code> 表示當前目錄中的文件數量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo *.* | wc</span></span>
<span class="line"><span>1       4      39</span></span></code></pre></div><h3 id="示例-11" tabindex="-1">示例-11 <a class="header-anchor" href="#示例-11" aria-label="Permalink to “示例-11”">​</a></h3><p>組合使用 <code>echo</code> 命令和 <code>wc</code> 命令來統計當前目錄中的所有目錄。 第二個 <code>1</code> 表示當前目錄中的目錄數量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo */ | wc</span></span>
<span class="line"><span>1       1       6</span></span></code></pre></div><h3 id="示例-12" tabindex="-1">示例-12 <a class="header-anchor" href="#示例-12" aria-label="Permalink to “示例-12”">​</a></h3><p>組合使用 <code>echo</code> 命令和 <code>wc</code> 命令來統計當前目錄中的所有文件和目錄。 <code>5</code> 表示當前目錄中的目錄和文件的數量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo * | wc</span></span>
<span class="line"><span>1 5 44</span></span></code></pre></div><h3 id="示例-13" tabindex="-1">示例-13 <a class="header-anchor" href="#示例-13" aria-label="Permalink to “示例-13”">​</a></h3><p>統計系統（整個系統）中的文件數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type f | wc -l</span></span>
<span class="line"><span>69769</span></span></code></pre></div><h3 id="示例-14" tabindex="-1">示例-14 <a class="header-anchor" href="#示例-14" aria-label="Permalink to “示例-14”">​</a></h3><p>統計系統（整個系統）中的文件夾數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d | wc -l</span></span>
<span class="line"><span>8819</span></span></code></pre></div><h3 id="示例-15" tabindex="-1">示例-15 <a class="header-anchor" href="#示例-15" aria-label="Permalink to “示例-15”">​</a></h3><p>運行以下命令來計算系統（整個系統）中的文件、文件夾、硬鏈接和符號鏈接數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d -exec echo dirs \\; -o -type l -exec echo symlinks \\; -o -type f -links +1 -exec echo hardlinks \\; -o -type f -exec echo files \\; | sort | uniq -c</span></span>
<span class="line"><span>   8779 dirs</span></span>
<span class="line"><span>  69343 files</span></span>
<span class="line"><span>     20 hardlinks</span></span>
<span class="line"><span>  11646 symlinks</span></span></code></pre></div><hr>`,57)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.2daygeek.com/how-to-count-the-number-of-files-and-folders-directories-in-linux/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/how-to-count-the-number-of-files-and-folders-directories-in-linux/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...s[2]||(s[2]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),i(e,{href:"https://github.com/Flowsnow"},{default:n(()=>[...s[3]||(s[3]=[a("Flowsnow",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",r]]);export{y as __pageData,C as default};
